using UnityEngine;
namespace Veilbreak.Feedback {
public struct FeedbackRequest {public Vector3 from,to;public Color color;public float size,duration;public bool beam;public int priority;}
/// <summary>Bounded particle/line pool; caller supplies simulation delta and event data.</summary>
public sealed class FeedbackPool:MonoBehaviour {
 sealed class Slot {public LineRenderer line;public ParticleSystem particles;public float remaining,duration,width;public int priority;public Color color;}
 readonly Slot[] slots=new Slot[48];Material material;int cursor;
 public void Initialize(Material material){this.material=material;}
 public void Emit(FeedbackRequest request){int index=-1;for(int i=0;i<slots.Length;i++){int n=(cursor+i)%slots.Length;if(slots[n]==null||slots[n].remaining<=0){index=n;break;}}if(index<0){int lowest=0;for(int i=1;i<slots.Length;i++)if(slots[i].priority<slots[lowest].priority)lowest=i;if(request.priority<=slots[lowest].priority)return;index=lowest;}cursor=(index+1)%slots.Length;var slot=slots[index];if(slot==null){var go=new GameObject("Feedback "+index);go.transform.SetParent(transform);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=material;line.positionCount=2;line.numCapVertices=3;var particles=go.AddComponent<ParticleSystem>();particles.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=particles.main;main.loop=false;main.playOnAwake=false;main.maxParticles=32;main.simulationSpace=ParticleSystemSimulationSpace.World;main.startLifetime=.3f;main.startSpeed=2;main.startSize=.05f;main.gravityModifier=.2f;var emission=particles.emission;emission.enabled=false;var shape=particles.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.1f;particles.GetComponent<ParticleSystemRenderer>().sharedMaterial=material;slots[index]=slot=new Slot{line=line,particles=particles};}
 slot.remaining=slot.duration=request.duration>0?request.duration:.25f;slot.priority=request.priority;slot.color=request.color;slot.width=Mathf.Max(.025f,request.size);slot.line.gameObject.SetActive(true);slot.line.enabled=request.beam;slot.line.startColor=request.color;slot.line.endColor=new Color(request.color.r,request.color.g,request.color.b,0);slot.line.widthMultiplier=Mathf.Max(.025f,request.size);slot.line.SetPosition(0,request.from);slot.line.SetPosition(1,request.to);slot.particles.transform.position=request.to;var main2=slot.particles.main;main2.startColor=request.color;slot.particles.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var emit=new ParticleSystem.EmitParams{startColor=request.color,startSize=Mathf.Max(.025f,request.size*.5f),startLifetime=.15f+request.size};slot.particles.Emit(emit,request.priority>1?24:8);}
 /// <summary>Beams flare to full width, pulse while they last and thin out as they fade.</summary>
 public void Advance(float delta){foreach(var slot in slots){if(slot==null||slot.remaining<=0)continue;slot.remaining-=delta;slot.particles.Simulate(delta,true,false);if(slot.remaining<=0){slot.line.gameObject.SetActive(false);continue;}
  if(!slot.line.enabled)continue;float age=1-slot.remaining/slot.duration,fade=1-age*age;slot.line.widthMultiplier=slot.width*Mathf.Lerp(1.6f,1,Mathf.Min(1,age*6))*(.85f+.15f*Mathf.Sin(age*40))*Mathf.Lerp(.35f,1,fade);
  var c=slot.color;c.a*=fade;slot.line.startColor=c;slot.line.endColor=new Color(c.r,c.g,c.b,c.a*.25f);}}
}
}
